{"sql": "CREATE TABLE IF NOT EXISTS lego_themes (
    id INTEGER PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    parent_id INTEGER
);

CREATE TABLE IF NOT EXISTS lego_colors (
    id INTEGER PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    rgb VARCHAR(7) NOT NULL,
    is_trans BOOLEAN DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS lego_parts (
    part_num VARCHAR(20) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    part_cat_id INTEGER,
    material VARCHAR(100)
);

CREATE TABLE IF NOT EXISTS lego_part_categories (
    id INTEGER PRIMARY KEY,
    name VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS lego_sets (
    set_num VARCHAR(20) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    year INTEGER,
    theme_id INTEGER REFERENCES lego_themes(id),
    num_parts INTEGER
);

CREATE TABLE IF NOT EXISTS lego_inventories (
    id INTEGER PRIMARY KEY,
    version INTEGER,
    set_num VARCHAR(20) REFERENCES lego_sets(set_num)
);

CREATE TABLE IF NOT EXISTS lego_inventory_parts (
    inventory_id INTEGER REFERENCES lego_inventories(id),
    part_num VARCHAR(20) REFERENCES lego_parts(part_num),
    color_id INTEGER REFERENCES lego_colors(id),
    quantity INTEGER,
    is_spare BOOLEAN DEFAULT FALSE,
    PRIMARY KEY (inventory_id, part_num, color_id)
);"}

{"sql": "-- Step 1: Create database role and permissions

-- Create the theme_analyst role
CREATE ROLE theme_analyst WITH NOLOGIN;

-- Grant SELECT permissions on reference tables
GRANT SELECT ON lego_themes TO theme_analyst;
GRANT SELECT ON lego_colors TO theme_analyst;
GRANT SELECT ON lego_parts TO theme_analyst;
GRANT SELECT ON lego_part_categories TO theme_analyst;

-- Grant SELECT permissions on main data tables
GRANT SELECT ON lego_sets TO theme_analyst;
GRANT SELECT ON lego_inventories TO theme_analyst;
GRANT SELECT ON lego_inventory_parts TO theme_analyst;"}

{"sql": "-- Step 4: Create theme assignment function
CREATE OR REPLACE FUNCTION get_user_theme_id()
RETURNS INTEGER AS $$
BEGIN
    -- Return 18 for theme_analyst role (Star Wars theme)
    -- Can be extended to support other themes in the future
    IF current_user = 'theme_analyst' THEN
        RETURN 18;
    ELSIF current_user = 'technic_analyst' THEN
        RETURN 1;
    ELSIF current_user = 'city_analyst' THEN
        RETURN 2;
    ELSE
        -- For other users, return NULL (no restriction)
        RETURN NULL;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;"}

{"sql": "-- Step 2: Enable Row-Level Security on the specified tables
ALTER TABLE lego_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventories ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventory_parts ENABLE ROW LEVEL SECURITY;"}

{"sql": "-- Policy 2: theme_inventories_policy on lego_inventories
CREATE POLICY theme_inventories_policy ON lego_inventories
FOR SELECT
USING (
    EXISTS (
        SELECT 1 FROM lego_sets 
        WHERE lego_sets.set_num = lego_inventories.set_num
        AND (lego_sets.theme_id = get_user_theme_id() OR get_user_theme_id() IS NULL)
    )
);"}

